//! The generator story's contract battery (plan §3.2's "Generated by
//! `xtask` into committed Rust (phf/trie). Also generates: docs …" —
//! the last named P2 slice, the one the crate docs carried as
//! "remaining" since P1 landed). Per the workspace TDD rule the spec
//! came first; the artifacts it pins are:
//!
//! * **the seam** — `codegen::GeneratedArtifact` is the one trait every
//!   committed derived artifact implements, and `codegen::artifacts()`
//!   is the stable list the `xtask` driver walks;
//! * **the roots index** — the generated perfect-hash table over the
//!   committed rows' distinct roots, the read side's fast path, with
//!   the linear scan kept as the documented differential oracle;
//! * **the registry docs** — the committed markdown page rendered from
//!   the same rows (`docs/REGISTRY.md`, the audit view the crate docs
//!   promise).
//!
//! The drift pins are the point of the story: a row edit that forgets
//! `cargo xtask gen-tables` fails HERE (in `cargo test`, before any
//! review), not in a downstream consumer.

use aeolus_data::codegen::{self, GeneratedArtifact};
use aeolus_data::registry::{LookupError, lookup, lookup_detailed, lookup_linear, roots};
use aeolus_data::roots_index;
use aeolus_data::rows::ROWS;

// ---------------------------------------------------------------------------
// 1. The seam
// ---------------------------------------------------------------------------

#[test]
fn the_seam_lists_the_committed_artifacts() {
    let listed: Vec<&str> = codegen::artifacts().iter().map(|a| a.name()).collect();
    assert_eq!(listed, ["roots-index", "registry-docs"]);
}

#[test]
fn every_artifact_commits_to_a_stable_workspace_path() {
    for artifact in codegen::artifacts() {
        assert!(
            !artifact.path().starts_with('/'),
            "{}: the path is workspace-relative",
            artifact.name()
        );
        let ext = std::path::Path::new(artifact.path())
            .extension()
            .and_then(|e| e.to_str())
            .unwrap_or_default();
        assert!(
            ext == "rs" || ext == "md",
            "{}: the path names a committed text file",
            artifact.name()
        );
    }
    let paths: Vec<&str> = codegen::artifacts().iter().map(|a| a.path()).collect();
    assert_eq!(
        paths,
        ["crates/aeolus-data/src/roots_index.rs", "docs/REGISTRY.md",]
    );
}

// ---------------------------------------------------------------------------
// 2. The drift pins — committed bytes == regeneration
// ---------------------------------------------------------------------------

#[test]
fn the_roots_index_committed_bytes_are_the_regeneration() {
    let committed = include_str!("../src/roots_index.rs");
    assert_eq!(
        committed,
        codegen::RootsIndex.generate(),
        "the committed roots index drifted from the rows — run `cargo xtask gen-tables`"
    );
}

#[test]
fn the_registry_docs_committed_bytes_are_the_regeneration() {
    let manifest = env!("CARGO_MANIFEST_DIR");
    let committed =
        std::fs::read_to_string(std::path::Path::new(manifest).join("../../docs/REGISTRY.md"))
            .expect("docs/REGISTRY.md is committed beside the rows");
    assert_eq!(
        committed,
        codegen::RegistryDocs.generate(),
        "the committed registry docs drifted from the rows — run `cargo xtask gen-tables`"
    );
}

#[test]
fn regeneration_is_deterministic() {
    for artifact in codegen::artifacts() {
        assert_eq!(
            artifact.generate(),
            artifact.generate(),
            "{}: two renders disagree — the generator carries nondeterminism",
            artifact.name()
        );
    }
}

// ---------------------------------------------------------------------------
// 3. The generated index's own invariants
// ---------------------------------------------------------------------------

#[test]
fn the_index_partitions_the_rows() {
    let mut seen = vec![false; ROWS.len()];
    for entry in &roots_index::ROOT_ENTRIES {
        assert!(!entry.rows.is_empty(), "{}: empty row list", entry.root);
        for &index in entry.rows {
            assert!(index < ROWS.len() as u16, "row index out of range");
            assert!(!seen[index as usize], "row {index} indexed twice");
            assert_eq!(
                ROWS[index as usize].root, entry.root,
                "row {index} indexed under the wrong root"
            );
            seen[index as usize] = true;
        }
    }
    assert!(
        seen.iter().all(|&s| s),
        "rows exist that no index entry covers"
    );
}

#[test]
fn every_distinct_root_is_indexed_exactly_once() {
    let distinct = roots();
    assert_eq!(
        distinct.len(),
        roots_index::ROOT_ENTRIES.len(),
        "the entry count must equal the distinct root count"
    );
    for root in distinct {
        let hits = roots_index::ROOT_ENTRIES
            .iter()
            .filter(|e| e.root == root)
            .count();
        assert_eq!(hits, 1, "root {root:?} indexed {hits} times");
    }
}

#[test]
fn every_entry_is_reachable_within_the_emitted_probe_bound() {
    for entry in &roots_index::ROOT_ENTRIES {
        let start = roots_index::slot_of(entry.root) as usize;
        let mut found = None;
        for step in 0..roots_index::PROBE_BOUND {
            let slot = (start + step) & roots_index::MASK;
            let occupant = roots_index::ROOT_SLOTS[slot];
            if occupant as usize
                == roots_index::ROOT_ENTRIES
                    .iter()
                    .position(|e| e.root == entry.root)
                    .expect("partitioned above")
            {
                found = Some(step);
                break;
            }
            assert!(
                occupant != roots_index::EMPTY,
                "{}: an empty slot at step {step} would end the probe first",
                entry.root
            );
        }
        assert!(
            found.is_some(),
            "{}: unreachable within PROBE_BOUND {}",
            entry.root,
            roots_index::PROBE_BOUND
        );
    }
}

#[test]
fn the_slot_table_size_carries_a_safe_load_factor() {
    assert!(
        roots_index::ROOT_ENTRIES.len() * 2 <= roots_index::ROOT_SLOTS.len(),
        "a half-full table at most — the probe bound stays small"
    );
    assert!(
        roots_index::ROOT_SLOTS.len().is_power_of_two(),
        "the mask arithmetic needs a power-of-two slot count"
    );
}

// ---------------------------------------------------------------------------
// 4. The differential battery — indexed read side == linear oracle
// ---------------------------------------------------------------------------

/// The linear scan the index replaced — the documented oracle
/// (`registry::lookup_linear`), kept byte-for-byte the pre-index
/// semantics so the battery cannot drift with the fast path.
fn linear_rows(body: &str) -> Vec<&'static aeolus_data::UtilityRow> {
    lookup_linear(body).collect()
}

#[test]
fn every_root_exact_and_valueful_answers_identically() {
    for root in roots() {
        for body in [root.to_string(), format!("{root}-4"), format!("{root}-red")] {
            let via_index: Vec<_> = lookup(&body).collect();
            let via_linear = linear_rows(&body);
            assert_eq!(
                via_index.len(),
                via_linear.len(),
                "{body:?}: row count disagrees with the linear oracle"
            );
            for (a, b) in via_index.iter().zip(&via_linear) {
                assert_eq!(a.root, b.root, "{body:?}: winning roots disagree");
                assert_eq!(a.targets, b.targets, "{body:?}: rows disagree");
            }
        }
    }
}

#[test]
fn the_multi_dash_composites_disambiguate_identically() {
    for body in [
        "rounded-tl-lg",
        "rounded-tr",
        "inset-x-2",
        "inset-y",
        "min-w-0",
        "max-w-full",
        "min-h-4",
        "border-t-2",
        "border-b",
        "bg-linear-to-r",
        "text-lg",
        "gap-x-4",
        "col-span-2",
        "z-10",
    ] {
        let via_index: Vec<_> = lookup(body).collect();
        let via_linear = linear_rows(body);
        let index_roots: Vec<_> = via_index.iter().map(|r| r.root).collect();
        let linear_roots: Vec<_> = via_linear.iter().map(|r| r.root).collect();
        assert_eq!(index_roots, linear_roots, "{body:?}: roots disagree");
    }
}

#[test]
fn the_adversarial_bodies_miss_identically() {
    for body in [
        "",
        "p-",
        "-p-4",
        "p--4",
        "P-4",
        "p-4-x",
        "not-a-utility",
        "pp-4",
        "pxx-4",
        "p-é",
        "ünïcøde",
        "w-[-2px]",
        "w-[32px]",
        "p-[1.5rem]",
        "p-]",
        "p-4/[a",
        "x-4",
        "zz",
        "----",
        "p-4-4-4-4-4",
    ] {
        let via_index: Vec<_> = lookup(body).collect();
        let via_linear = linear_rows(body);
        let index_roots: Vec<_> = via_index.iter().map(|r| r.root).collect();
        let linear_roots: Vec<_> = via_linear.iter().map(|r| r.root).collect();
        assert_eq!(index_roots, linear_roots, "{body:?}: roots disagree");
    }
}

#[test]
fn a_deterministic_fuzz_batteries_the_index_against_the_oracle() {
    // LCG, fixed seed: the same 4000 bodies every run (no proptest dep —
    // the registry's zero-dependency discipline holds for dev tooling).
    let mut state: u64 = 0x2b99_2ddf_a232_49d6;
    let alphabet: &[u8] = b"abcdefghijklmnopqrstuvwxyz-0123456789[]/%.";
    let roots_text: Vec<String> = roots().iter().map(|r| (*r).to_string()).collect();
    for _ in 0..4000u32 {
        state = state
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        let len = (state >> 33) as usize % 12;
        let pick = |state: &mut u64| {
            *state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            alphabet[((*state >> 33) as usize) % alphabet.len()] as char
        };
        let mut body = String::new();
        for _ in 0..len {
            body.push(pick(&mut state));
        }
        // One in four bodies starts with a real root (the near-miss
        // shapes are where a hash table would drift the prefix rule).
        if body.len().is_multiple_of(4)
            && let Some(root) = roots_text.get((state as usize) % roots_text.len())
        {
            body = format!("{root}{body}");
        }
        let via_index: Vec<_> = lookup(&body).collect();
        let via_linear = linear_rows(&body);
        let index_roots: Vec<_> = via_index.iter().map(|r| r.root).collect();
        let linear_roots: Vec<_> = via_linear.iter().map(|r| r.root).collect();
        assert_eq!(index_roots, linear_roots, "{body:?}: roots disagree");
    }
}

#[test]
fn the_typed_misses_carry_the_same_mode_as_the_oracle() {
    // The registry's own body-matches rule, replicated from the public
    // rows: exact, or root + `-` (the dash-aligned prefix rule).
    let matches = |body: &str, root: &str| {
        body == root || (body.starts_with(root) && body.as_bytes().get(root.len()) == Some(&b'-'))
    };
    for body in [
        "not-a-utility",
        "p-red",
        "rounded-tl-red",
        "text-not-a-size",
    ] {
        let detailed = lookup_detailed(body);
        let linear = linear_rows(body);
        match detailed {
            Ok(rows) => {
                assert!(
                    !linear.is_empty(),
                    "{body:?}: detailed answered rows where the oracle misses"
                );
                let detailed_roots: Vec<_> = rows.iter().map(|r| r.root).collect();
                let linear_roots: Vec<_> = linear.iter().map(|r| r.root).collect();
                assert_eq!(detailed_roots, linear_roots, "{body:?}: rows disagree");
            }
            Err(LookupError::UnknownRoot { .. }) => {
                assert!(
                    linear.is_empty(),
                    "{body:?}: UnknownRoot where the oracle answers rows"
                );
                assert!(
                    !ROWS.iter().any(|row| matches(body, row.root)),
                    "{body:?}: UnknownRoot where a registered root prefixes the body"
                );
            }
            Err(LookupError::ShapeRejected { root, tried, .. }) => {
                // The oracle agrees no row ACCEPTS the body, but the
                // winning root must be the longest registered root the
                // body's dash-aligned prefixes reach, and the tried
                // labels must describe that root's own shapes.
                assert!(
                    linear.is_empty(),
                    "{body:?}: ShapeRejected where the oracle answers rows"
                );
                let expected = ROWS
                    .iter()
                    .filter(|row| matches(body, row.root))
                    .map(|row| row.root.len())
                    .max()
                    .expect("ShapeRejected implies a winning root");
                let winner = ROWS
                    .iter()
                    .find(|row| row.root.len() == expected && matches(body, row.root))
                    .expect("the longest root exists")
                    .root;
                assert_eq!(
                    root, winner,
                    "{body:?}: the rejected root is not the winner"
                );
                assert!(!tried.is_empty(), "{body:?}: no tried labels");
            }
        }
    }
}

#[test]
fn the_read_side_rows_carry_the_registry_contract_unchanged() {
    // Spot pin: the index did not reorder or re-shape what the read
    // side hands back (the compile stage's value pass keys on this).
    let rows: Vec<_> = lookup("p-4").collect();
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].root, "p");
    assert_eq!(rows[0].group, "padding");
    let rows: Vec<_> = lookup("bg-primary").collect();
    assert!(rows.iter().any(|r| r.root == "bg"));
}
